<script setup lang="ts">import{computed,ref}from"vue";import{buildDiaryCalendar}from"@/domain/diary/calendar";import type{DiaryEntryRecord}from"@/domain/diary/records";const props=defineProps<{entries:DiaryEntryRecord[]}>();const current=ref(new Date());const days=computed(()=>buildDiaryCalendar(current.value.getFullYear(),current.value.getMonth(),props.entries));const label=computed(()=>new Intl.DateTimeFormat("pt-PT",{month:"long",year:"numeric"}).format(current.value));function move(delta:number){current.value=new Date(current.value.getFullYear(),current.value.getMonth()+delta,1)}</script><template><section class="panel diary-calendar" aria-labelledby="calendar-title"><div class="section-heading"><button class="button button-secondary" type="button" @click="move(-1)">Anterior</button><h2 id="calendar-title">{{label}}</h2><button class="button button-secondary" type="button" @click="move(1)">Seguinte</button></div><div class="calendar-weekdays" aria-hidden="true"><span>Seg</span><span>Ter</span><span>Qua</span><span>Qui</span><span>Sex</span><span>Sáb</span><span>Dom</span></div><div class="calendar-grid"><article v-for="day in days" :key="day.date" :class="{'is-outside':!day.inMonth}"><strong>{{day.day}}</strong><ul><li v-for="entry in day.entries" :key="entry.id">{{entry.expand?.titulo?.titulo||'Registo'}}</li></ul></article></div></section></template>
